--
-- Table structure for table `subjects`
--

DROP TABLE IF EXISTS `subjects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subjects` (
  `subject_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `credit` int DEFAULT '0',
  `total_hours_per_week` int DEFAULT '0',
  `program_id` int NOT NULL,
  `subject_department` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `type_prac_or_theory` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `user_id` int DEFAULT NULL,
  `subject_code` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `semester` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ltpa` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`subject_id`),
  KEY `program_id` (`program_id`),
  KEY `title` (`title`),
  KEY `program_id_2` (`program_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `subjects_ibfk_1` FOREIGN KEY (`program_id`) REFERENCES `programs` (`program_id`) ON UPDATE CASCADE,
  CONSTRAINT `subjects_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=752 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

