DROP TABLE IF EXISTS `venues`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `venues` (
  `venue_id` int NOT NULL AUTO_INCREMENT,
  `venue_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `capacity` int NOT NULL DEFAULT '0',
  `location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `quality` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `department` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mnos` int NOT NULL DEFAULT '1',
  `tnos` int NOT NULL DEFAULT '1',
  `wnos` int NOT NULL DEFAULT '1',
  `thnos` int NOT NULL DEFAULT '1',
  `frnos` int NOT NULL DEFAULT '1',
  `satnos` int NOT NULL DEFAULT '1',
  `sunnos` int NOT NULL DEFAULT '1',
  `totalnos` int NOT NULL DEFAULT '7',
  PRIMARY KEY (`venue_id`),
  UNIQUE KEY `venue_name` (`venue_name`),
  KEY `type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
